const q = $json.query || $json;
const mode = q['hub.mode'] || q.hubMode || '';
const token = q['hub.verify_token'] || q.hubVerifyToken || '';
const challenge = q['hub.challenge'] || q.hubChallenge || '';
const expected = 'llbox-whatsapp-verify';
const ok = mode === 'subscribe' && token === expected;
return [{ json: { ok, challenge: String(challenge), mode, token } }];

const raw = $('Webhook Trigger').item.json;
const body = raw.body || raw;
const change = body?.entry?.[0]?.changes?.[0]?.value || {};
const message = Array.isArray(change.messages) ? change.messages[0] : null;
const statuses = Array.isArray(change.statuses) ? change.statuses : [];
const isStatusOnly = !message && statuses.length > 0;
if (isStatusOnly) {
  return [{ json: { skip: true, isMessage: false, reason: 'delivery_status' } }];
}
if (!message) {
  return [{ json: { skip: true, isMessage: false, reason: 'no_message', debugKeys: Object.keys(body || {}) } }];
}
const text = message.type === 'text' ? String(message.text?.body || '').trim() : '';
return [{
  json: {
    skip: false,
    isMessage: true,
    unsupported: message.type !== 'text' || !text,
    phone: String(message.from || ''),
    text,
    messageId: message.id || '',
    waProfileName: change.contacts?.[0]?.profile?.name || '',
    phoneNumberId: change.metadata?.phone_number_id || ''
  }
}];

const parsed = $('Parse WhatsApp Payload').item.json;
const cfg = $('Config').item.json;
const lookup = $json.data || $json;
const contact = lookup.contact || {};
const phone = parsed.phone;
const text = parsed.text || '';
const waProfileName = parsed.waProfileName || '';
const knownName = (contact.name || '').trim();
const openaiKey = String(cfg.openaiApiKey || '').trim();

const extractOrder = (value) => {
  const m = String(value || '').match(/[A-Z0-9][A-Z0-9._-]{4,}/i);
  return m ? m[0] : '';
};

const fallback = () => {
  const lower = text.toLowerCase();
  const looksLikeName = (value) => {
    const v = String(value || '').trim();
    if (!v || v.length < 2 || v.length > 40) return false;
    if (/\d/.test(v)) return false;
    if (/otp|order|delivery|locker|box|register|confirm|hi|hello|hey/.test(v.toLowerCase())) return false;
    return /^[\p{L} .'-]+$/u.test(v);
  };
  let action = 'chat';
  let name = knownName;
  let orderReference = extractOrder(text) || contact.lastOrderReference || '';
  let reply = '';
  let saveName = '';
  let awaiting = false;
  if (!knownName && looksLikeName(text)) {
    saveName = text.trim();
    name = saveName;
    action = 'save_name';
    reply = `Nice to meet you, ${name}. How can I help you today?`;
  } else if (!knownName) {
    awaiting = true;
    action = 'ask_name';
    reply = 'Welcome to LLBox. What is your name?';
  } else if (/(otp|open|rider|driver)/i.test(lower) && extractOrder(text)) {
    action = 'resolve';
    reply = '';
  } else if (/(register)/i.test(lower) && extractOrder(text)) {
    action = 'register';
    reply = '';
  } else if (/(locker|find my)/i.test(lower)) {
    action = 'find';
    reply = '';
  } else {
    action = 'chat';
    reply = `Hi ${name}, I can help with deliveries, locker lookup, or rider OTP.`;
  }
  return { action, phone, name, saveName, awaitingName: awaiting, orderReference, text, reply, boxId: 3, waProfileName, registered: Boolean(knownName), aiUsed: false };
};

let result = fallback();

if (openaiKey && openaiKey !== 'PASTE_OPENAI_API_KEY' && !parsed.unsupported) {
  try {
    const ai = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.openai.com/v1/chat/completions',
      headers: {
        Authorization: 'Bearer ' + openaiKey,
        'Content-Type': 'application/json',
      },
      body: {
        model: 'gpt-4o-mini',
        temperature: 0.4,
        response_format: { type: 'json_object' },
        messages: [
          {
            role: 'system',
            content: 'You are the LLBox WhatsApp assistant for smart locker deliveries in Saudi Arabia. Be short, friendly, and useful. If knownName is not empty, greet the user by that name and NEVER ask for their name again. If knownName is empty, ask for their name once. If the user message is clearly a person name, set action to save_name. For locker OTP use action resolve. To register a delivery use action register. To find a locker use action find. Otherwise use action chat. Return ONLY JSON with keys: action, reply, name, saveName, awaitingName, orderReference. action must be one of: chat, ask_name, save_name, resolve, register, find. reply is the WhatsApp text. Do not invent OTP codes.'
          },
          {
            role: 'user',
            content: JSON.stringify({
              knownName,
              awaitingName: Boolean(contact.awaitingName) && !knownName,
              phone,
              lastOrderReference: contact.lastOrderReference || '',
              userMessage: text
            })
          }
        ]
      },
      json: true,
    });
    const raw = ai.choices?.[0]?.message?.content || '{}';
    const parsedAi = JSON.parse(raw);
    const allowed = ['chat', 'ask_name', 'save_name', 'resolve', 'register', 'find'];
    const action = allowed.includes(parsedAi.action) ? parsedAi.action : 'chat';
    result = {
      action,
      phone,
      name: parsedAi.name || knownName || parsedAi.saveName || '',
      saveName: parsedAi.saveName || (action === 'save_name' ? text.trim() : knownName),
      awaitingName: Boolean(parsedAi.awaitingName) && !knownName && action === 'ask_name',
      orderReference: parsedAi.orderReference || extractOrder(text) || contact.lastOrderReference || '',
      text,
      reply: parsedAi.reply || result.reply,
      boxId: 3,
      waProfileName,
      registered: Boolean(knownName || parsedAi.saveName),
      aiUsed: true
    };
    if ((action === 'resolve' || action === 'register') && !result.orderReference) {
      result.action = 'chat';
      result.reply = (result.name ? `Hi ${result.name}, ` : '') + 'Please send the order reference. Example: ABC123';
    }
  } catch (e) {
    result.aiError = String(e.message || e);
  }
}

return [{ json: result }];

const decided = $('ChatGPT Brain').item.json;
const action = decided.action;
let reply = decided.reply;
const name = decided.name || 'there';

if (action === 'resolve') {
  const res = $json;
  if (res.success && res.data?.otp) {
    const d = res.data;
    reply = `Hi ${name}, your OTP is ${d.otp}.\nLocker: ${d.boxCode || ''}\nAddress: ${d.address || ''}\nExpires: ${d.otpExpiresAt || ''}\nEnter this code on the box keypad to open it.`;
  } else {
    reply = `Hi ${name}, I could not get an OTP yet. ${res.message || 'Please check the order reference.'}`;
  }
} else if (action === 'register') {
  const res = $json;
  if (res.success) {
    reply = `Hi ${name}, delivery ${decided.orderReference} is registered for locker ${res.data?.boxCode || 'QA-PROD-TEST-BOX'}. The rider can now request OTP with this order reference.`;
  } else {
    reply = `Hi ${name}, I could not register that delivery. ${res.message || ''}`;
  }
} else if (action === 'find') {
  const res = $json;
  if (res.success && res.data?.userFound) {
    reply = `Hi ${name}, your locker is ${res.data.locker}.`;
  } else {
    reply = `Hi ${name}, I could not find a locker on this WhatsApp number yet.`;
  }
}

return [{
  json: {
    phone: decided.phone,
    name,
    saveName: decided.saveName || decided.name,
    awaitingName: decided.awaitingName,
    lastIntent: action,
    lastOrderReference: decided.orderReference || '',
    lastInboundText: decided.text || '',
    reply
  }
}];
